import pickle

def check_pickle(itorg, seq):
    for proto in range(pickle.HIGHEST_PROTOCOL + 1):
        d = pickle.dumps(itorg, proto)
        it = pickle.loads(d)
        assert type(itorg) == type(it), ('assertEqual', type(itorg), type(it))
        assert list(it) == seq, ('assertEqual', list(it), seq)
        it = pickle.loads(d)
        try:
            next(it)
        except StopIteration:
            assert not seq[1:], ('assertFalse', seq[1:])
            continue
        d = pickle.dumps(it, proto)
        it = pickle.loads(d)
        assert list(it) == seq[1:], ('assertEqual', list(it), seq[1:])

def _t():
    for data in ('abc', range(5), tuple(enumerate('abc')), range(1, 17, 5)):
        check_pickle(reversed(data), list(data)[::-1])
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
